import {renderRejection} from './cooling-rejection.js';
import {chillerBalance,operatingPoint,weatherDay,towerLedger,heatReuse,decisionFeedback} from './heat-rejection-model.js';
const n=(value,digits=2)=>Number(value.toFixed(digits)).toLocaleString('en-US');
const stat=(value,label,extra='')=>`<div class="h-stat ${extra}"><strong>${value}</strong><span>${label}</span></div>`;
const arrow='<span class="h-arrow" aria-hidden="true">→</span>';
const node=(title,detail='',extra='')=>`<div class="h-node ${extra}"><b>${title}</b>${detail?`<span>${detail}</span>`:''}</div>`;
const strip=text=>`<p class="h-strip">${text}</p>`;
const stack=content=>`<div class="h-stack">${content}</div>`;
const input=text=>`<p class="h-input">${text}</p>`;
const panel=(title,body,extra='')=>`<section class="h-panel ${extra}"><h2>${title}</h2>${body}</section>`;
function powerBar(p){return `<div class="h-power"><div class="h-power-header"><span>Site input</span><b class="${p.electricalFits?'':'h-warning'}">${n(p.totalMW)} / 10 MW</b></div><div class="h-power-track" aria-label="${n(p.totalMW)} MW required against a 10 MW limit"><span class="h-it" style="width:${p.requestedITMW/11*100}%"></span><span class="h-cooling" style="width:${p.coolingMW/11*100}%"></span><span class="h-other" style="width:${p.otherMW/11*100}%"></span><i style="left:${10/11*100}%"></i></div><div class="h-legend"><span><i class="h-it"></i>IT ${n(p.requestedITMW)} MW</span><span><i class="h-cooling"></i>Cooling ${n(p.coolingMW)} MW</span><span><i class="h-other"></i>Other 0.4 MW</span></div></div>`;}
const brief=()=>`<div class="h-brief"><div><span>Site input limit</span><b>10 MW</b></div><div><span>Other electrical load</span><b>0.4 MW</b></div><div><span>Air-cooled plant</span><b>COP 4 · 8.5 MW thermal</b></div><div><span>Tower makeup supply</span><b class="h-warning">Unavailable</b></div></div>`;
export function heatRejectionVisual(id,state,compact=false){
 if(['rejection','weather','approach-outdoors','plant-options'].includes(id))return `<div class="h-legacy"><svg role="img" aria-label="${{'rejection':'Dry coil and evaporative tower heat and water paths','weather':'Dry-bulb and wet-bulb temperatures','approach-outdoors':'Outdoor conditions through three heat-transfer interfaces','plant-options':'Selected cooling-plant heat path'}[id]}" viewBox="${compact?'0 0 372 580':'0 0 1160 420'}">${renderRejection(id,compact,state)}</svg></div>`;
 if(id==='heat-rejection-purpose')return stack(`<div class="h-flow h-overview">${node('Capture','Chip → air or liquid','h-chip')}${arrow}${node('Transport','Rack loop → facility loop','h-water')}${arrow}${node('Reject','Facility → environment','h-outdoors')}</div><div class="h-heat-line"><span>IT electrical input</span><b>Heat flows toward the environment →</b></div>${strip('The outdoor plant also has its own electrical and water requirements.')}`);
 if(id==='chiller-balance'){
  const m=chillerBalance();return stack(`${input('Steady state · pumps and fans outside the chiller boundary')}<div class="h-chiller"><div>${stat('10 MW','Cooling duty at the evaporator')}</div>${arrow}<section class="h-machine"><div class="h-work"><b>+ 2 MW</b><span>Compressor electricity</span><i>↓</i></div><div class="h-machine-body"><span>Evaporator</span><b>Refrigeration</b><span>Condenser</span></div></section>${arrow}<div>${stat(`${n(m.condenserMW)} MW`,'Condenser heat','h-warm')}</div></div><p class="h-equation">Heat rejected = cooling duty + compressor work</p>`);
 }
 if(id==='cooling-cop'){
  const m=chillerBalance(),plant=state.copBoundary==='plant';return stack(`${input('Same 10 MW cooling duty · 2 MW compressor · 0.5 MW pumps and fans')}<div class="h-cop-layout"><div class="h-fraction"><span>10 MW cooling</span><b>${plant?'2 + 0.5':'2'} MW electricity</b></div><span class="h-equals">=</span>${stat(n(plant?m.plantCOP:m.compressorCOP),plant?'Whole-plant COP':'Compressor-boundary COP')}</div><div class="h-boundary ${plant?'expanded':''}">${node('Compressor','2 MW')}${node('Pumps + fans','0.5 MW',plant?'':'outside')}</div>${strip('COP measures heat moved per unit of work.')}`);
 }
 if(id==='hot-hour'){
  const p=operatingPoint({condition:state.condition});return stack(`${input('Proposed IT load 8 MW · all cooling electricity included')}<div class="h-two">${panel('Thermal screen',`${stat(`${n(p.thermalMW)} MW`,'Available cooling duty')}${strip('8 MW of IT heat fits.','')}`,'h-positive')}${panel('Electrical screen',`${stat(`COP ${p.cop}`,'Plant operating point')}${strip(`${n(p.coolingMW)} MW of cooling electricity`)}`)}</div>${powerBar(p)}${strip(p.electricalFits?'Both screens pass at this supplied operating point.':'Thermal capacity passes. Site electrical input fails.')}`);
 }
 if(id==='two-ceilings'){
  const p=operatingPoint({condition:state.condition});return stack(`${input(`10 MW supply · 0.4 MW other · plant COP ${p.cop}`)}<p class="h-equation">P<sub>IT</sub> + P<sub>IT</sub> / ${p.cop} + 0.4 ≤ 10 MW</p><div class="h-two">${panel('Electrical ceiling',`${stat(`${n(p.electricalMW)} MW`,`(10 − 0.4) / (1 + 1/${p.cop})`)}`)}${panel('Thermal ceiling',stat(`${n(p.thermalMW)} MW`,'Supplied plant capacity'))}</div><div class="h-verdict">${stat(`${n(p.feasibleMW)} MW`,'Lower ceiling sets feasible IT power')}</div>`);
 }
 if(id==='weather-bins'){
  const m=weatherDay();return stack(`${input('12 cool hours, then 12 hot hours · requested IT load 8 MW')}<div class="h-bin-table" role="table" aria-label="Two weather bins"><div role="row" class="h-table-head"><span>Operating bin</span><span>IT power</span><span>Cooling power</span></div>${m.bins.map(b=>`<div role="row"><span>${b.condition==='cool'?'Cool · COP 8':'Hot · COP 4'}<small>12 hours</small></span><b>${n(b.itMW)} MW</b><b>${n(b.coolingMW)} MW</b></div>`).join('')}</div><div class="h-three">${stat(`${n(m.itMWh)} MWh`,'IT energy')}${stat(`${n(m.coolingMWh)} MWh`,'Cooling energy')}${stat(`${n(m.otherMWh)} MWh`,'Other energy')}</div><p class="h-equation">Site energy = <b>${n(m.facilityMWh)} MWh</b></p>`);
 }
 if(id==='abilene-cooling')return `<div class="h-case"><figure><img src="../assets/references/distribution-abilene-data-halls.jpg" alt="Oracle aerial photograph of the original Abilene data-center campus and its data halls."><figcaption><a href="https://www.oracle.com/data-centers/" target="_blank" rel="noopener">Oracle · Abilene aerial · July 15, 2026</a></figcaption></figure><div class="h-case-copy"><p class="h-date">Crusoe design account · August 2025</p><div class="h-vertical">${node('Recirculating facility water','Heat collected from IT')}<span class="h-arrow">↓</span>${node('Air-cooled chiller','Heat + compressor work')}<span class="h-arrow">↓</span>${node('Outdoor air','Non-evaporative rejection')}</div><p class="h-credit"><a href="https://www.crusoe.ai/resources/blog/an-inside-look-at-the-abilene-ai-data-center" target="_blank" rel="noopener">Crusoe: initial fill and maintenance remain separate water uses.</a></p></div></div>`;
 if(id==='closed-loop-water'){
  const tower=state.closedSink==='tower';return stack(`<div class="h-flow">${node('Equipment loop','Coolant recirculates','h-water')}${arrow}${node('Chiller','Transfers heat + adds work')}${arrow}${node(tower?'Condenser water → tower':'Outdoor air',tower?'Separate circuit evaporates water':'No intentional water evaporation',tower?'h-warm':'h-outdoors')}</div><div class="h-resource-line"><span class="h-loop-symbol">↻</span><p>The equipment loop stays closed.</p></div>${strip(tower?'Tower makeup replaces evaporation and blowdown.':'Initial fill and maintenance water remain separate.')}`);
 }
 if(id==='water-ledger'){
  const m=towerLedger({cycles:state.cycles});return stack(`${input(`One-day tower ledger · evaporation fixed at 100 m³ · concentration ratio C = ${m.cycles}`)}<div class="h-water-balance"><div class="h-water-input">${stat(`${n(m.makeupM3)} m³`,'Makeup M')}${arrow}</div><div class="h-tower"><span class="h-vapor">↑ ${n(m.evaporationM3)} m³ evaporation</span><div class="h-tower-body"><b>Tower</b><span>↻ recirculation</span></div><span class="h-blowdown">↓ ${n(m.blowdownM3)} m³ blowdown</span></div></div><div class="h-two h-formulas"><p>M = E + B</p><p>B = E / (C − 1)</p></div>${strip('Drift, leaks and storage change excluded; water chemistry sets feasible C.')}`);
 }
 if(id==='water-metrics'){
  const m=towerLedger({returnKnown:state.returnKnown});return stack(`${input('One-day ledger · 100 MWh IT · 120 MWh facility · C = 5')}<div class="h-three">${panel('Site intake',stat('125 m³','1.25 L / IT kWh'))}${panel('Consumption',stat(m.consumptionM3===null?'Unresolved':'100 m³',m.consumptionM3===null?'Return destination is missing':'1.00 L / IT kWh'))}${panel('Facility / IT energy',stat('1.20','120 / 100 MWh'))}</div><div class="h-return-ledger"><span>25 m³ blowdown</span>${arrow}<b>${state.returnKnown?'Verified return to the same basin':'Return destination unknown'}</b></div>${strip('For PUE or WUE comparisons, match the period and name the accounting boundary.')}`);
 }
 if(id==='heat-reuse'){
  const m=heatReuse({receiverHours:state.receiverHours});return stack(`${input('4 MW available continuously · receiver can accept 2 MW')}<div class="h-reuse-chart"><div><b>Data-center heat</b><div class="h-day"><span class="h-generated">4 MW × 24 h = 96 MWh</span></div></div><div><b>Heat accepted</b><div class="h-day"><span class="h-accepted" style="width:${state.receiverHours/24*100}%"></span></div></div><div class="h-hours"><span>0 h</span><span>6 h</span><span>12 h</span><span>24 h</span></div></div><div class="h-three">${stat(`${n(m.acceptedMWh)} MWh`,'Accepted heat')}${stat(`${n(m.acceptedFraction*100)}%`,'Share of daily heat')}${stat(`${n(m.remainingMWh)} MWh`,'Still needs a destination','h-warm')}</div>${strip('Compatible delivery temperature assumed; distribution losses excluded.')}`);
 }
 if(id==='reuse-interface')return stack(`<div class="h-flow">${node('Warm coolant','Available temperature + flow')}${arrow}${node('Delivery interface','Exchanger; heat pump if needed')}${arrow}${node('Receiving load','Required temperature + schedule')}</div><div class="h-two">${panel('Accepted heat',`<p>Count heat delivered across the customer boundary.</p>`)}${panel('Customer unavailable',`<p>Keep an adequate alternate rejection path.</p>`,'h-warm')}</div>${strip('Include heat-pump and pumping electricity in the comparison.')}`);
 if(id==='water-restriction')return stack(`${input('Hot-hour brief · tower makeup unavailable')}<div class="h-two">${panel('Tower path',`${node('Makeup supply','Unavailable','h-off')}<span class="h-arrow">↓</span>${node('Evaporative rejection','Unavailable','h-off')}`,'h-path')}${panel('Air-cooled alternate',`${node('Qualified hot-hour point','COP 4 · 8.5 MW thermal')}<span class="h-arrow">↓</span>${node('Site electrical budget','10 MW including IT + cooling + other')}`,'h-path')}</div>${strip('Choose the IT operating point that fits the surviving complete path.')}`);
 if(id==='heat-rejection-check'){
  const feedback=decisionFeedback(state.choice);return `<div class="h-check"><div class="h-check-brief"><p class="h-input">Hot-hour operating brief</p>${brief()}</div><div class="h-check-answer">${state.revealed?`<div class="h-feedback ${feedback.correct?'h-good':'h-bad'}"><h2>${feedback.correct?'Both limits pass.':'Recheck the complete path.'}</h2><p>${feedback.text}</p></div>`:`<div class="h-answer-choices">${[['full','Air-cooled plant · keep 8 MW IT'],['reduce','Air-cooled plant · reduce IT to 7.68 MW'],['tower','Keep the tower · the rack loop is closed']].map(([key,label])=>`<button type="button" data-plan="${key}" aria-pressed="${state.choice===key}">${label}</button>`).join('')}</div>`}<button type="button" id="decision-reveal" ${!state.choice?'disabled':''}>${state.revealed?'Try another plan':'Check this plan'}</button></div></div>`;
 }
 throw new RangeError(`Unknown heat-rejection scene: ${id}`);
}
